mapper.select:
select mp.product_id as productId, mp.category_id as categoryId, mc.category_name as categoryName, mp.product_name as productName, mp.unit_name as unitName, mp.market_price as marketPrice, mp.sale_price as salePrice, mp.cover_image as coverImage, mp.detail_images as detailImages, mp.video_url as videoUrl, mp.freight_amount as freightAmount, mp.stock_total as stockTotal, mp.sales_count as salesCount, mp.shelf_status as shelfStatus, mp.sort_num as sortNum, mp.del_flag as delFlag, mp.create_time as createTime, mp.update_time as updateTime, mp.remark as remark from mall_product mp left join mall_category mc on mp.category_id = mc.category_id and mc.del_flag = 0 where mp.del_flag = 0
and mp.category_id = #{categoryId}
and mc.category_name like concat('%', #{categoryName}, '%')
and mp.product_name like concat('%', #{productName}, '%')
and mp.shelf_status = #{shelfStatus}
order by mp.product_id desc

select count(1)
from mall_product mp
where mp.del_flag = 0

    and mp.category_id = #{categoryId}


    and mp.product_name like concat('%', #{productName}, '%')


    and mp.shelf_status = #{shelfStatus}

select mp.product_id, mp.category_id, mp.product_name, mp.unit_name, mp.market_price, mp.sale_price, mp.cover_image, mp.detail_images, mp.video_url, mp.freight_amount, mp.stock_total, mp.sales_count, mp.shelf_status, mp.sort_num, mp.del_flag, mp.create_time, mp.update_time, mp.remark from mall_product mp where mp.del_flag = 0
and mp.category_id = #{categoryId}
and mp.product_name like concat('%', #{productName}, '%')
and mp.shelf_status = #{shelfStatus}
order by mp.product_id desc limit 1

mapper.update:
update mall_product
set del_flag = 1
where product_id = #{productId}
